import { useState } from 'react';
import { panelStyle } from './Component.styles';

export type Relation = 'less' | 'equal' | 'greater';
export type Props = { onCompare: (relation: Relation) => void };

function parseInteger(input: string) {
  const trimmed = input.trim();
  if (!/^-?\d+$/.test(trimmed)) return null;
  const value = Number(trimmed);
  return Number.isSafeInteger(value) ? value : null;
}

export function Component({ onCompare }: Props) {
  const [left, setLeft] = useState('');
  const [right, setRight] = useState('');
  const [result, setResult] = useState<Relation | null>(null);
  const [hasError, setHasError] = useState(false);

  return (
    <div data-testid="panel" style={panelStyle}>
      <label>
        Left
        <input
          type="text"
          value={left}
          onChange={(event) => setLeft(event.target.value)}
        />
      </label>
      <label>
        Right
        <input
          type="text"
          value={right}
          onChange={(event) => setRight(event.target.value)}
        />
      </label>
      <button
        type="button"
        onClick={() => {
          const leftValue = parseInteger(left);
          const rightValue = parseInteger(right);
          if (leftValue === null || rightValue === null) {
            setHasError(true);
            return;
          }
          const relation = leftValue < rightValue
            ? 'less'
            : leftValue > rightValue
              ? 'greater'
              : 'equal';
          setResult(relation);
          setHasError(false);
          onCompare(relation);
        }}
      >
        Compare
      </button>
      {hasError && <div role="alert">Invalid integers</div>}
      <output aria-label="Result">{result ?? 'Not compared'}</output>
    </div>
  );
}
```

